46	func TestPublishAndDeliver(t *testing.T) {
47		e := apitest.New(t)
48		ctx := context.Background()
49		now := e.Clock.Now()
50		all, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, now)
51		paid, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/paid", Events: []string{"invoice.paid"}, Secret: "whsec_b", Enabled: true}, now)
52		_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/off", Events: []string{"*"}, Secret: "whsec_c", Enabled: false}, now)
53		_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Globex.ID, URL: "https://hooks.globex.example/", Events: []string{"*"}, Secret: "whsec_d", Enabled: true}, now)
54	
55		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
56			t.Fatal(err)
57		}
58		n, err := e.Webhooks.RunDue(ctx)
59		if err != nil || n != 1 {
60			t.Fatalf("RunDue = %d, %v (only the endpoint for every event wants customer.created)", n, err)
61		}
62		reqs := e.HTTP.Requests()
63		if len(reqs) != 1 || reqs[0].URL != all.URL || reqs[0].Method != http.MethodPost {
64			t.Fatalf("requests = %+v", reqs)
65		}
66		if got, want := reqs[0].Header.Get("Tally-Signature"), webhooks.Sign("whsec_a", reqs[0].Body); got != want {
67			t.Fatalf("signature %q, want %q", got, want)
68		}
69		var body webhooks.Body
70		if err := json.Unmarshal(reqs[0].Body, &body); err != nil || body.Type != "customer.created" || reqs[0].Header.Get("Tally-Event-Id") != body.ID {
71			t.Fatalf("body = %s (%v)", reqs[0].Body, err)
72		}
73		ds := e.Store.Deliveries(e.Acme.ID, all.ID)
74		if len(ds) != 1 || ds[0].Status != store.DeliverySucceeded || ds[0].Attempts != 1 || ds[0].ResponseStatus != 200 {
75			t.Fatalf("deliveries = %+v", ds)
76		}
77	
78		e.HTTP.Respond = func(r apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
79		_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"})
80		if n, _ := e.Webhooks.RunDue(ctx); n != 2 {
81			t.Fatalf("RunDue = %d, want 2", n)
82		}
83		for _, ep := range []store.WebhookEndpoint{all, paid} {
84			ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
85			last := ds[len(ds)-1]
86			if last.Status != store.DeliveryFailed || last.ResponseStatus != 500 || last.Error == "" {
87				t.Fatalf("delivery to %s = %+v", ep.URL, last)
88			}
89		}
90		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
91			t.Fatalf("a failed delivery was sent again: %d", n)
92		}
93	}
