args.old_string:
func (s *Service) deliver(ctx context.Context, d store.Delivery) {
	status, errText := 0, ""
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	switch {
	case !ok || !ep.Enabled:
		errText = "the endpoint is disabled or was deleted"
	case !eok:
		errText = "the event no longer exists"
	default:
		status, errText = s.send(ctx, ep, e)
	}
	now := s.clock.Now()
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		if errText == "" {
			d.Status = store.DeliverySucceeded
		} else {
			d.Status = store.DeliveryFailed
		}
		return nil
	})
}

args.new_string:
// deliver makes an attempt at a delivery and reports whether it did. A delivery whose endpoint is disabled or whose event is
// gone fails without being sent, and that is not an attempt.
func (s *Service) deliver(ctx context.Context, d store.Delivery) bool {
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	if !ok || !ep.Enabled {
		s.stop(d, "the endpoint is disabled or was deleted")
		return false
	}
	e, ok := s.store.EventByID(d.EventID)
	if !ok {
		s.stop(d, "the event no longer exists")
		return false
	}
	status, errText := s.send(ctx, ep, e)
	s.attempted(ctx, d, status, errText)
	return true
}

// stop fails a delivery for good without an attempt.
func (s *Service) stop(d store.Delivery, errText string) {
