// runFor runs RunDue every minute for d, as the service's ticker does, and fails the test on an error.
func runFor(t *testing.T, e *apitest.Env, d time.Duration) {
	t.Helper()
	for end := e.Clock.Now().Add(d); e.Clock.Now().Before(end); e.Clock.Advance(time.Minute) {
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
	}
}

// onlyDelivery returns the one delivery an endpoint has.
func onlyDelivery(t *testing.T, e *apitest.Env, endpoint store.WebhookEndpoint) store.Delivery {
	t.Helper()
	ds := e.Store.Deliveries(e.Acme.ID, endpoint.ID)
	if len(ds) != 1 {
		t.Fatalf("deliveries = %+v, want 1", ds)
	}
	return ds[0]
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, err := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusServiceUnavailable, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	delays := []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
	for i := 1; i <= 7; i++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", i, n, err)
		}
		d := onlyDelivery(t, e, ep)
		if d.Attempts != i || d.ResponseStatus != http.StatusServiceUnavailable || d.Error == "" || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(e.Clock.Now()) {
			t.Fatalf("after attempt %d: %+v", i, d)
		}
		if i == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the last attempt: %+v", d)
			}
			b, _ := json.Marshal(d)
			if !strings.Contains(string(b), `"next_attempt_at":null`) {
				t.Fatalf("JSON = %s, want next_attempt_at null", b)
			}
			break
		}
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(delays[i-1])) {
			t.Fatalf("after attempt %d: %+v, want the next attempt %s later", i, d, delays[i-1])
		}
		e.Clock.Advance(delays[i-1] - time.Second)
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d made a second too early", i+1)
		}
		e.Clock.Advance(time.Second)
	}
	if n := len(e.HTTP.Requests()); n != 7 {
		t.Fatalf("requests = %d, want 7", n)
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again: %d", n)
	}
}

func TestRetryOnNoAnswerAndRedirect(t *testing.T) {
	for name, respond := range map[string]func(apitest.Request) (int, error){
		"no answer": func(apitest.Request) (int, error) { return 0, errors.New("connection refused") },
		"redirect":  func(apitest.Request) (int, error) { return http.StatusFound, nil },
	} {
		t.Run(name, func(t *testing.T) {
			e := apitest.New(t)
			ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, e.Clock.Now())
			e.HTTP.Respond = respond
			if err := e.Webhooks.Publish(context.Background(), e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
				t.Fatal(err)
			}
			if n, _ := e.Webhooks.RunDue(context.Background()); n != 1 {
				t.Fatalf("RunDue = %d", n)
			}
			if d := onlyDelivery(t, e, ep); d.Status != store.DeliveryPending || d.Attempts != 1 || d.Error == "" || d.NextAttemptAt == nil {
				t.Fatalf("delivery = %+v, want pending and retried", d)
			}
		})
	}
}

func TestGoneDisablesEndpoint(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, e.Clock.Now())
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusGone, nil }
	for _, typ := range []string{"customer.created", "customer.updated"} {
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, typ, map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
		t.Fatalf("RunDue = %d, want 1: the endpoint is disabled after its first answer", n)
	}
	if len(e.HTTP.Requests()) != 1 {
		t.Fatalf("requests = %d, want 1", len(e.HTTP.Requests()))
	}
	got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID)
	if got.Enabled || got.DisabledReason != "gone" {
		t.Fatalf("endpoint = %+v", got)
	}
	for _, d := range e.Store.Deliveries(e.Acme.ID, ep.ID) {
		if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
			t.Fatalf("delivery = %+v, want failed for good", d)
		}
	}
	if msgs := e.Mail.Messages(); len(msgs) != 0 {
		t.Fatalf("a 410 emailed %d messages, want none", len(msgs))
	}
}

func TestFailureEmail(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, e.Clock.Now())
	_, _ = e.AddMember(e.Acme, "second@acme.example", store.RoleOwner)
	_, _ = e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	publish := func() {
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
	}

	// The first event fails for good at +34h36m; the second, published 10 hours later, fails 10 hours after that, within 24
	// hours of the first email, so the owners are not mailed again. A third, 60 hours in, is mailed again.
	publish()
	runFor(t, e, 10*time.Hour)
	publish()
	runFor(t, e, 40*time.Hour)
	msgs := e.Mail.Messages()
	if len(msgs) != 2 {
		t.Fatalf("after two failures, %d emails: %+v", len(msgs), msgs)
	}
	for _, m := range msgs {
		if m.Subject != "Webhook endpoint failing: https://hooks.acme.example/all" || (m.To != e.Acme.Owner.Email && m.To != "second@acme.example") {
			t.Fatalf("email = %+v", m)
		}
	}
	if d := e.Store.Deliveries(e.Acme.ID, ep.ID); len(d) != 2 || d[1].Status != store.DeliveryFailed {
		t.Fatalf("deliveries = %+v", d)
	}

	publish()
	runFor(t, e, 40*time.Hour)
	if n := len(e.Mail.Messages()); n != 4 {
		t.Fatalf("after a failure 24 hours later, %d emails, want 4", n)
	}
}

